#!/usr/bin/env python3
"""Adjust the Android project generated by `tauri android init`.

* Add the YtdlPlugin (downloads with youtubedl-android) and its dependency.
* Register as a share target so links can be shared to the app.

* Extract native libraries at install time so the bundled FFmpeg executables
  (packed as lib*.so) live in nativeLibraryDir, where Android allows exec.
* Copy those executables into jniLibs for every ABI that was built.
"""
import re
import shutil
import sys
from pathlib import Path

root = Path(__file__).resolve().parent.parent
gen = root / "app" / "src-tauri" / "gen" / "android"
ffmpeg_dir = Path(sys.argv[1]) if len(sys.argv) > 1 else None

YTDL_VERSION = "0.18.1"

gradle = gen / "app" / "build.gradle.kts"
text = gradle.read_text()
if "youtubedl-android" not in text:
    dep = f'    implementation("io.github.junkfood02.youtubedl-android:library:{YTDL_VERSION}")\n'
    if re.search(r"^dependencies\s*\{", text, re.M):
        text = re.sub(r"^dependencies\s*\{\n", lambda m: m.group(0) + dep, text, count=1, flags=re.M)
    else:
        text += "\ndependencies {\n" + dep + "}\n"
if "excludes" not in text:
    # The app ships arm64-v8a and x86_64 only; drop the library's 32-bit binaries.
    text = re.sub(
        r"android\s*\{",
        'android {\n    packaging {\n        jniLibs {\n            excludes += setOf("lib/armeabi-v7a/**", "lib/x86/**")\n        }\n    }',
        text,
        count=1,
    )
if "useLegacyPackaging" not in text:
    text = re.sub(r"android\s*\{", "android {\n    packaging {\n        jniLibs {\n            useLegacyPackaging = true\n        }\n    }", text, count=1)
    gradle.write_text(text)
    print("patched", gradle)

plugin_src = root / "app" / "src-tauri" / "android" / "YtdlPlugin.kt"
plugin_dst = gen / "app" / "src" / "main" / "java" / "app" / "pocketreel" / "converter" / "YtdlPlugin.kt"
plugin_dst.parent.mkdir(parents=True, exist_ok=True)
shutil.copy2(plugin_src, plugin_dst)
print("copied", plugin_dst)

manifest = gen / "app" / "src" / "main" / "AndroidManifest.xml"
m = manifest.read_text()
if "android.intent.action.SEND" not in m:
    share = """
            <intent-filter android:label="Convert with Pocket Reel">
                <action android:name="android.intent.action.SEND" />
                <category android:name="android.intent.category.DEFAULT" />
                <data android:mimeType="text/plain" />
            </intent-filter>"""
    # Add after the launcher intent-filter of the main activity.
    m = re.sub(r"(<category android:name=\"android.intent.category.LAUNCHER\"\s*/>\s*</intent-filter>)", lambda x: x.group(1) + share, m, count=1)
if "launchMode" not in m:
    m = m.replace("<activity", '<activity\n            android:launchMode="singleTask"', 1)
if "android.permission.INTERNET" not in m:
    m = m.replace("<application", '<uses-permission android:name="android.permission.INTERNET" />\n    <application', 1)
if "extractNativeLibs" not in m:
    m = m.replace("<application", '<application\n        android:extractNativeLibs="true"', 1)
manifest.write_text(m)
print("patched", manifest)

if ffmpeg_dir:
    for abi_dir in ffmpeg_dir.iterdir():
        if not abi_dir.is_dir():
            continue
        dest = gen / "app" / "src" / "main" / "jniLibs" / abi_dir.name
        dest.mkdir(parents=True, exist_ok=True)
        for f in abi_dir.glob("lib*.so"):
            shutil.copy2(f, dest / f.name)
            print("copied", f.name, "->", dest)
